export function countFenceSegments(posts: number[]): number {
  if (posts.length < 2) return 0;
  const sorted = [...posts].sort((a, b) => a - b);
  let segments = 0;
  for (let i = 1; i < sorted.length; i++) {
    if (sorted[i] !== sorted[i - 1]) segments++;
  }
  return segments;
}

