export function coalesceMerge(base, override) {
  const b = (base === null || base === undefined) ? {} : base;
  const o = (override === null || override === undefined) ? {} : override;
  const result = {};
  const keys = new Set([...Object.keys(b), ...Object.keys(o)]);
  for (const key of keys) {
    const hasOverride = Object.prototype.hasOwnProperty.call(o, key);
    const overrideVal = o[key];
    if (hasOverride && overrideVal !== null && overrideVal !== undefined) {
      result[key] = overrideVal;
    } else {
      result[key] = b[key];
    }
  }
  return result;
}

