export function splitBillEvenly(totalCents, numPeople) {
  const base = Math.trunc(totalCents / numPeople);
  const remainder = totalCents - base * numPeople;
  const result = new Array(numPeople);
  for (let i = 0; i < numPeople; i++) {
    result[i] = base + (i < remainder ? 1 : 0);
  }
  return result;
}

