export function convertCurrencyAmount(amountCents, exchangeRate) {
  const raw = amountCents * exchangeRate;
  if (raw === 0) return 0;
  const sign = raw < 0 ? -1 : 1;
  const abs = Math.abs(raw);
  const rounded = Math.floor(abs + 0.5 + 1e-9);
  return sign * rounded;
}

