export function flattenOnce(arr: unknown[]): unknown[] {
  const result: unknown[] = [];
  for (const item of arr) {
    if (Array.isArray(item)) {
      for (const sub of item) {
        result.push(sub);
      }
    } else {
      result.push(item);
    }
  }
  return result;
}

