export function truncateSafe(str, maxLen) {
  if (typeof str !== "string") throw new TypeError("str must be a string");
  if (maxLen < 0) throw new RangeError("maxLen must be >= 0");
  if (str.length <= maxLen) return str;
  if (maxLen === 0) return "";

  const ELLIPSIS = "...";
  if (maxLen <= ELLIPSIS.length) {
    return ELLIPSIS.slice(0, maxLen);
  }

  let cut = maxLen - ELLIPSIS.length;
  const code = str.charCodeAt(cut - 1);
  if (code >= 0xd800 && code <= 0xdbff) {
    cut -= 1;
  }
  return str.slice(0, cut) + ELLIPSIS;
}

