export function splitLimit(str, sep, limit) {
  if (typeof str !== "string") throw new TypeError("str must be a string");
  if (typeof sep !== "string") throw new TypeError("sep must be a string");
  if (limit <= 0) return [];

  if (sep === "") {
    const chars = str.split("");
    if (chars.length <= limit) return chars;
    const head = chars.slice(0, limit - 1);
    const tail = chars.slice(limit - 1).join("");
    return head.concat([tail]);
  }

  const parts = [];
  let rest = str;
  while (parts.length < limit - 1) {
    const idx = rest.indexOf(sep);
    if (idx === -1) break;
    parts.push(rest.slice(0, idx));
    rest = rest.slice(idx + sep.length);
  }
  parts.push(rest);
  return parts;
}

