export function trimChars(str, chars) {
  if (typeof str !== "string") throw new TypeError("str must be a string");
  if (typeof chars !== "string") throw new TypeError("chars must be a string");
  if (chars === "") return str;

  const set = new Set(chars.split(""));
  let start = 0;
  let end = str.length;

  while (start < end && set.has(str[start])) {
    start++;
  }
  while (end > start && set.has(str[end - 1])) {
    end--;
  }

  return str.slice(start, end);
}

