export function countOccurrences(str, needle, overlapping = false) {
  if (typeof str !== "string") throw new TypeError("str must be a string");
  if (typeof needle !== "string") throw new TypeError("needle must be a string");

  if (needle === "") return str.length + 1;
  if (needle.length > str.length) return 0;

  let count = 0;
  let pos = 0;
  const step = overlapping ? 1 : needle.length;

  while (pos <= str.length - needle.length) {
    const idx = str.indexOf(needle, pos);
    if (idx === -1) break;
    count++;
    pos = idx + step;
  }

  return count;
}

