export function parseCsvLine(line) {
  if (typeof line !== "string") throw new TypeError("line must be a string");

  const fields = [];
  let field = "";
  let inQuotes = false;
  let i = 0;

  while (i < line.length) {
    const ch = line[i];

    if (inQuotes) {
      if (ch === '"') {
        if (line[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        } else {
          inQuotes = false;
          i += 1;
          continue;
        }
      } else {
        field += ch;
        i += 1;
        continue;
      }
    } else {
      if (ch === '"' && field === "") {
        inQuotes = true;
        i += 1;
        continue;
      } else if (ch === ",") {
        fields.push(field);
        field = "";
        i += 1;
        continue;
      } else {
        field += ch;
        i += 1;
        continue;
      }
    }
  }

  fields.push(field);
  return fields;
}

